import { useState } from "react";

export function Hint({ text }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div>
      <button type="button" aria-expanded={isOpen} onClick={() => setIsOpen(!isOpen)}>
        {isOpen ? "Hide hint" : "Show hint"}
      </button>
      {isOpen && <p className="hint">{text}</p>}
    </div>
  );
}
```

| Manual DOM | React |
|---|---|
| find the element. | not needed. |
| createElement and append. | put `<p>` in the returned JSX. |
| remove on close. | return nothing for it when closed. |
| update button text. | derive it from isOpen. |
| keep all of it in sync. | React reconciles automatically. |

